-- crash-edit/history
-- Every recorded version of a crash and of its people (also people since removed, found by the crash id kept in
-- their snapshot), newest first, with who made the change and why.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = 100
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

select r.id, r.entity_type as "entityType", r.entity_id as "entityId", r.version, r.data, r.reason, r.created_at as "createdAt",
       r.actor_id as "actorId", u.name as "actorName", r.submission_id as "submissionId"
from revisions r left join users u on u.id = r.actor_id
where (r.entity_type = 'crash' and r.entity_id = $1)
   or (r.entity_type = 'person' and (r.data->>'crashId') = $2::text)
order by r.created_at desc, r.id desc
limit $3;
